import time

def charge_with_retry(payload: dict, attempts: int = 3) -> dict:
    for i in range(attempts):
        try:
            return processor.charge(payload)
        except ProcessorBusy:
            time.sleep(2 ** i)
    raise ProcessorBusy("gave up")

